// M4 T16a: every committed TA-Lib reference fixture parses with the loader and, when it was
// generated by TA-Lib (scripts/agents/talib_reference.py via the talib-reference workflow), the
// TypeScript indicators match it within the fixture tolerance (AGT-032).
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { compareToFixture, parseTaLibFixture } from "@/lib/agents/indicators";

const DIR = path.join(process.cwd(), "tests", "fixtures", "agents", "indicators");
const files = readdirSync(DIR).filter((f) => f.endsWith(".json"));

describe("committed TA-Lib reference fixtures", () => {
  it("there is at least the hand-verified fixture", () => {
    expect(files).toContain("handverified_6bars.json");
  });
  for (const f of files) {
    it(`${f} parses and matches within tolerance`, () => {
      const fx = parseTaLibFixture(JSON.parse(readFileSync(path.join(DIR, f), "utf8")));
      expect(Object.keys(fx.expected).length).toBeGreaterThan(0);
      for (const [id, diff] of Object.entries(compareToFixture(fx))) {
        expect(diff, `${f} ${id}`).toBeLessThanOrEqual(fx.tolerance);
      }
    });
  }
});
